import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  return {
    send(value) {
      return value;
    },
  };
}

test('route registration order and count are preserved', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({method: r.method, path: r.path})),
    [
      {method: 'GET', path: '/accounts/:id'},
      {method: 'POST', path: '/accounts'},
      {method: 'GET', path: '/health'},
      {method: 'GET', path: '/orders/:id'},
      {method: 'DELETE', path: '/orders/:id'},
    ],
  );
});

test('GET /accounts/:id successfully returns response', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  assert.ok(route);
  let nextCalled = false;
  const result = await route.handler({id: 'acc1'}, createMockRes(), () => {
    nextCalled = true;
  });
  assert.equal(result, 'account:acc1');
  assert.equal(nextCalled, false);
});

test('GET /accounts/:id forwards error to next on failure', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  assert.ok(route);
  let forwardedError = null;
  await route.handler({id: 'acc1', fail: true}, createMockRes(), err => {
    forwardedError = err;
  });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account read');
});

test('POST /accounts successfully returns response', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  assert.ok(route);
  let nextCalled = false;
  const result = await route.handler({id: 'acc2'}, createMockRes(), () => {
    nextCalled = true;
  });
  assert.equal(result, 'created:acc2');
  assert.equal(nextCalled, false);
});

test('POST /accounts forwards error to next on failure', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  assert.ok(route);
  let forwardedError = null;
  await route.handler({id: 'acc2', fail: true}, createMockRes(), err => {
    forwardedError = err;
  });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'account create');
});

test('GET /health synchronous route is preserved', () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
  assert.ok(route);
  let nextCalled = false;
  const result = route.handler({id: 'h1'}, createMockRes(), () => {
    nextCalled = true;
  });
  assert.equal(result, 'ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id successfully returns response', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  assert.ok(route);
  let nextCalled = false;
  const result = await route.handler({id: 'ord1'}, createMockRes(), () => {
    nextCalled = true;
  });
  assert.equal(result, 'ORD1');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id forwards error to next on failure', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  assert.ok(route);
  let forwardedError = null;
  await route.handler({id: 'ord1', fail: true}, createMockRes(), err => {
    forwardedError = err;
  });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order read');
});

test('DELETE /orders/:id successfully returns response', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  assert.ok(route);
  let nextCalled = false;
  const result = await route.handler({id: 'ord2'}, createMockRes(), () => {
    nextCalled = true;
  });
  assert.equal(result, 'deleted:ord2');
  assert.equal(nextCalled, false);
});

test('DELETE /orders/:id forwards error to next on failure', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  assert.ok(route);
  let forwardedError = null;
  await route.handler({id: 'ord2', fail: true}, createMockRes(), err => {
    forwardedError = err;
  });
  assert.ok(forwardedError instanceof Error);
  assert.equal(forwardedError.message, 'order delete');
});

test('documentation string and unrelated helper are untouched', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");
  await assert.rejects(() => unrelatedHelper(), {message: 'helper'});
  await assert.rejects(() => auditCallback(), {message: 'audit'});
});

